/**
 * The card's view of a settled `gis_view` call.
 *
 * `meta` is authored by this plugin's own host half (tool.ts), but it arrives
 * through the durable session log, so it is parsed defensively: an older host
 * half, a truncated log, or a replayed session from a previous plugin version
 * can all present a shape this build did not write.
 */

/** Locale binding handed down by the shell. */
export type Translate = (key: string) => string

/** What the map card needs to render one layer. */
export interface GisCardMeta {
  title: string
  featureCount: number
  truncated: boolean
  geojson: unknown
}

/** The settled-vs-pending tool-call block shape the slot passes in. */
export interface ToolCallBlock {
  kind?: string
  meta?: unknown
  isError?: boolean
  content?: ReadonlyArray<{ type?: string; text?: string }>
  error?: { name?: string; code?: string }
}

/** True once the block carries a result rather than an in-flight call. */
export function isSettled(block: ToolCallBlock): boolean {
  return 'kind' in block && block.kind !== undefined
}

/**
 * Extract the card metadata, or null when the block cannot render a map
 * (still running, errored, or carrying a meta shape this build cannot use).
 * @param block - the tool-call block from the slot.
 * @returns renderable metadata, or null.
 */
export function cardMetaOf(block: ToolCallBlock): GisCardMeta | null {
  if (!isSettled(block) || block.isError === true) return null
  const meta = block.meta
  if (typeof meta !== 'object' || meta === null) return null
  const candidate = meta as Partial<GisCardMeta>
  const geojson = candidate.geojson as { type?: string } | undefined
  if (geojson?.type !== 'FeatureCollection') return null
  return {
    title: typeof candidate.title === 'string' ? candidate.title : '',
    featureCount: typeof candidate.featureCount === 'number' ? candidate.featureCount : 0,
    truncated: candidate.truncated === true,
    geojson,
  }
}

/**
 * The error text to show when a call failed, so a bad path or an unreachable
 * service explains itself in the card instead of only in the model's reply.
 * @param block - the tool-call block from the slot.
 * @returns the message, or null when the call did not fail.
 */
export function errorTextOf(block: ToolCallBlock): string | null {
  if (!isSettled(block) || block.isError !== true) return null
  const text = (block.content ?? [])
    .map(item => (item.type === 'text' ? item.text ?? '' : ''))
    .join('\n')
    .trim()
  if (text !== '') return text
  const error = block.error
  return error === undefined ? null : `${error.name ?? 'Error'}: ${error.code ?? 'unknown'}`
}
