/**
 * dsh-plugin-gis client: replaces the default `gis_view` tool row with an
 * interactive map card.
 *
 * Built by tsdown into the __ModuleLoader__ factory bundle at
 * client/client.js; react is the only external, resolved from the loader
 * module table.
 */

import { createElement as h } from 'react'
import { en, zh } from './locales.ts'
import { MapCard } from './MapCard.tsx'
import { cardMetaOf, errorTextOf, type ToolCallBlock, type Translate } from './meta.ts'
import styles from './Map.module.css'

const NS = 'dsh-gis'

/** The subset of the locale service this plugin touches. */
interface LocaleService {
  register(namespace: string, dicts: { zh: Record<string, string>; en: Record<string, string> }): unknown
  bind(namespace: string): Translate
}

/** The subset of the slots service this plugin touches. */
interface SlotsService {
  inject(slot: string, register: () => unknown): void
  register(meta: Record<string, unknown>, component: (props: never) => unknown): unknown
}

/** The client cordis context shape this plugin relies on. */
interface GisClientContext {
  effect(callback: () => unknown, label?: string): void
  locale: LocaleService
  slots: SlotsService
}

export const name = 'dsh-gis'
export const inject = ['slots', 'locale']

/**
 * Register the map card against the toolview slot.
 * @param ctx - the client context.
 */
export function apply(ctx: GisClientContext): void {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-gis: dictionaries')
  const t = ctx.locale.bind(NS)

  ctx.slots.inject('tool.call.toolview', () => ctx.slots.register({
    name: 'tool.call.toolview',
    key: 'gis_view',
    locale: NS,
  }, (props: { block: ToolCallBlock }) => {
    const { block } = props
    const failure = errorTextOf(block)
    if (failure !== null) {
      return h('div', { className: styles.card },
        h('div', { className: styles.header }, h('span', { className: styles.title }, t('card.error'))),
        h('pre', { className: styles.error }, failure))
    }
    const meta = cardMetaOf(block)
    // Still running, or a result this build cannot read: fall through to the
    // shell's default row rather than rendering an empty frame.
    if (meta === null) return null
    return h(MapCard, { meta, t })
  }))
}
