/**
 * The map card rendered in place of a `gis_view` tool call.
 *
 * OpenLayers is bundled rather than injected: the shell's loader table has no
 * mapping library, and OL is the one that handles projected CRSs and ArcGIS
 * services the way a GIS user expects. The card only ever receives WGS84 from
 * the host, so no projection database is needed in the browser.
 */

import { useCallback, useEffect, useMemo, useRef, useState, type ReactElement } from 'react'
import Map from 'ol/Map.js'
import View from 'ol/View.js'
import TileLayer from 'ol/layer/Tile.js'
import VectorLayer from 'ol/layer/Vector.js'
import VectorSource from 'ol/source/Vector.js'
import OSM from 'ol/source/OSM.js'
import GeoJSON from 'ol/format/GeoJSON.js'
import { Circle, Fill, Stroke, Style } from 'ol/style.js'
import { fromLonLat } from 'ol/proj.js'
import type { FeatureLike } from 'ol/Feature.js'
import styles from './Map.module.css'
import type { GisCardMeta, Translate } from './meta.ts'

/** Vector styling: one accent color, sized so points stay visible at extent. */
const ACCENT = '#2f6df6'

const VECTOR_STYLE = new Style({
  fill: new Fill({ color: 'rgba(47, 109, 246, 0.18)' }),
  stroke: new Stroke({ color: ACCENT, width: 1.5 }),
  image: new Circle({
    radius: 4,
    fill: new Fill({ color: ACCENT }),
    stroke: new Stroke({ color: '#ffffff', width: 1 }),
  }),
})

/**
 * Fit a map's view to a vector source's extent. Module-level so both the
 * toolbar button and the resize observer share one definition.
 * @param map - the map to move.
 * @param source - the layer whose extent to frame.
 */
function fitTo(map: Map, source: VectorSource): void {
  // getExtent() returns an empty/infinite extent for a source with no geometry.
  const extent = source.getExtent() as number[] | null
  if (extent === null || !extent.every(Number.isFinite) || extent[0] > extent[2]) return
  map.getView().fit(extent, { padding: [24, 24, 24, 24], maxZoom: 18, duration: 200 })
}

/** Props the toolview slot hands this component, narrowed to what it uses. */
export interface MapCardProps {
  meta: GisCardMeta
  t: Translate
}

/**
 * Format one attribute value for the inspector row. Objects are JSON so a
 * nested attribute is still readable rather than rendering as [object Object].
 * @param value - the raw attribute value.
 * @returns a displayable string.
 */
export function formatValue(value: unknown): string {
  if (value === null || value === undefined) return '—'
  if (typeof value === 'object') return JSON.stringify(value)
  return String(value)
}

/**
 * Render the interactive map plus an attribute inspector for the clicked
 * feature.
 * @param props - card metadata and the locale binding.
 * @returns the card element.
 */
export function MapCard({ meta, t }: MapCardProps): ReactElement {
  const container = useRef<HTMLDivElement | null>(null)
  const mapRef = useRef<Map | null>(null)
  const [selected, setSelected] = useState<Record<string, unknown> | null>(null)
  const [basemapFailed, setBasemapFailed] = useState(false)

  const source = useMemo(() => {
    const features = new GeoJSON().readFeatures(meta.geojson, {
      dataProjection: 'EPSG:4326',
      featureProjection: 'EPSG:3857',
    })
    return new VectorSource({ features })
  }, [meta.geojson])

  /** Fit the view to the layer; the initial world view stays when it is empty. */
  const fit = useCallback(() => {
    const map = mapRef.current
    if (map !== null) fitTo(map, source)
  }, [source])

  useEffect(() => {
    const element = container.current
    if (element === null) return undefined
    const basemap = new OSM()
    // A tile error is the normal case on an air-gapped machine; downgrade to a
    // vector-only map rather than leaving the user with a blank grid.
    const onTileError = (): void => setBasemapFailed(true)
    basemap.on('tileloaderror', onTileError)
    const map = new Map({
      target: element,
      layers: [new TileLayer({ source: basemap }), new VectorLayer({ source, style: VECTOR_STYLE })],
      view: new View({ center: fromLonLat([104, 35]), zoom: 3 }),
      controls: [],
    })
    mapRef.current = map
    const onClick = (event: { pixel: number[] }): void => {
      let hit: FeatureLike | undefined
      map.forEachFeatureAtPixel(event.pixel, feature => {
        hit = feature
        return true
      })
      if (hit === undefined) setSelected(null)
      else {
        const properties = { ...hit.getProperties() }
        delete properties.geometry
        setSelected(properties)
      }
    }
    map.on('click', onClick as never)

    // A tool card can mount while its container has no size — a collapsed
    // turn, an off-screen transcript, a parent that lays out a frame later.
    // OpenLayers measures once at mount and would otherwise stay blank
    // forever, so watch the box and re-measure when it becomes real.
    // Callbacks are coalesced into one frame: resize fires in bursts during a
    // window drag, and updateSize + fit are both layout-thrashing.
    let frame = 0
    const observer = new ResizeObserver(() => {
      if (frame !== 0) return
      frame = requestAnimationFrame(() => {
        frame = 0
        if (element.clientWidth === 0 || element.clientHeight === 0) return
        map.updateSize()
        fitTo(map, source)
      })
    })
    observer.observe(element)

    return () => {
      if (frame !== 0) cancelAnimationFrame(frame)
      observer.disconnect()
      basemap.un('tileloaderror', onTileError)
      map.setTarget(undefined)
      map.dispose()
      mapRef.current = null
    }
  }, [source])

  // Fit once the layer is on the map, and again whenever the layer changes.
  useEffect(() => {
    fit()
  }, [fit])

  const empty = source.getFeatures().length === 0
  const countLabel = t('card.features').replace('{count}', String(meta.featureCount))
    + (meta.truncated ? t('card.truncated') : '')

  return (
    <div className={styles.card} data-tool="gis_view">
      <div className={styles.header}>
        <span className={styles.title}>{meta.title}</span>
        <span className={styles.count}>{countLabel}</span>
        <button type="button" className={styles.action} onClick={fit} aria-label={t('card.fit')} title={t('card.fit')}>
          ⤢
        </button>
      </div>
      <div className={styles.map} ref={container} />
      {empty ? <div className={styles.notice}>{t('card.empty')}</div> : null}
      {basemapFailed ? <div className={styles.notice}>{t('card.offline')}</div> : null}
      {selected === null ? null : (
        <div className={styles.attributes}>
          {Object.entries(selected).map(([key, value]) => (
            <div className={styles.attrRow} key={key}>
              <span className={styles.attrKey}>{key}</span>
              <span className={styles.attrValue}>{formatValue(value)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
